<?php
require_once __DIR__.'/../includes/auth.php'; require __DIR__.'/../includes/db.php';
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $date=$_POST['expense_date']??date('Y-m-d'); $cat=trim($_POST['category']??'General'); $desc=trim($_POST['description']??''); $amount=money_value($_POST['amount']??0); $car=(int)($_POST['car_id']??0)?:null; $user=$_SESSION['user_id']??null; if($desc&&$amount>0){$stmt=$conn->prepare("INSERT INTO expenses (expense_date,category,description,amount,car_id,created_by) VALUES (?,?,?,?,?,?)"); $stmt->bind_param('sssdii',$date,$cat,$desc,$amount,$car,$user); $stmt->execute(); $msg='Expense saved.';} }
$cars=$conn->query("SELECT cars.id,cars.reg_no,makes.name AS make_name,models.name AS model_name,car_years.year AS car_year FROM cars JOIN makes ON cars.make_id=makes.id JOIN models ON cars.model_id=models.id JOIN car_years ON cars.year_id=car_years.id ORDER BY makes.name,models.name");
$list=$conn->query("SELECT e.*,ca.reg_no FROM expenses e LEFT JOIN cars ca ON e.car_id=ca.id ORDER BY e.expense_date DESC,e.id DESC");
?>
<!DOCTYPE html><html><head><title>Expense Tracking</title></head><body><?php include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/leftsidebar.php';?><div class="content-page"><h2>Expense Tracking</h2><?php if($msg):?><p class="success-msg"><?=h($msg)?></p><?php endif;?><div class="card-box"><form method="POST" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end"><div><label>Date</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>"></div><div><label>Category</label><select name="category"><?php foreach(['Fuel','Maintenance','Insurance','Staff','Office','Other'] as $c):?><option><?=h($c)?></option><?php endforeach;?></select></div><div><label>Description</label><input name="description" required></div><div><label>Amount</label><input type="number" step="0.01" name="amount" required></div><div><label>Car</label><select name="car_id"><option value="">General</option><?php while($c=$cars->fetch_assoc()):?><option value="<?=h($c['id'])?>"><?=h(car_display_name($c))?></option><?php endwhile;?></select></div><button>Save Expense</button></form></div><table class="table" border="1" cellpadding="10"><tr><th>Date</th><th>Category</th><th>Description</th><th>Car</th><th>Amount</th></tr><?php $total=0; if($list&&$list->num_rows):while($e=$list->fetch_assoc()):$total+=(float)$e['amount'];?><tr><td><?= h(cr_date($e['expense_date'])) ?></td><td><?=h($e['category'])?></td><td><?=h($e['description'])?></td><td><?=h($e['reg_no'])?></td><td><?=money((float)$e['amount'])?></td></tr><?php endwhile; ?><tr><th colspan="4">Total</th><th><?=money($total)?></th></tr><?php else:?><tr><td colspan="5">No expenses yet.</td></tr><?php endif;?></table></div></body></html>
